#!/bin/bash

# Replace the vendored libraries in this directory by the versions below,
# downloaded from npm.  Run this script after changing a version, and commit
# its output.  It is not a build step:  the extension loads the committed
# files directly.

set -euo pipefail

DJOT_VERSION=0.3.2
DOMPURIFY_VERSION=3.4.17
TEMML_VERSION=0.14.0
HIGHLIGHTJS_VERSION=11.12.0
MERMAID_VERSION=12.3.0

VENDOR=$(cd "$(dirname "$0")" && pwd)
SCRATCH=$(mktemp -d)
trap 'rm -rf "$SCRATCH"' EXIT

# Download the given npm package and print the directory that holds its files.
# Arguments: an npm package name such as "@djot/djot", and a version.
fetch() {
  local dir
  dir="$SCRATCH/$(echo "$1" | tr -c 'a-zA-Z0-9.\n' '_')"
  mkdir -p "$dir"
  (cd "$dir" && npm pack --silent "$1@$2" > /dev/null && tar -xzf ./*.tgz)
  echo "$dir/package"
}

# Write to standard output the given CSS file, with its rules nested inside
# the given selector, so that they apply only within the elements that it
# matches.  Rules that cannot be nested (@font-face) or that only Firefox
# understands (@-moz-document) are dropped.
# Arguments: a CSS file, and a selector such as "html.djot-viewer".
scope_css() {
  node - "$1" "$2" << 'EOF'
const [file, selector] = process.argv.slice(2);
const css = require("fs").readFileSync(file, "utf8");
const dropped = /^@(font-face|-moz-document)\b/;
let out = "";
let i = 0;
while (i < css.length) {
  if (css.startsWith("/*", i)) {
    const end = css.indexOf("*/", i + 2) + 2;
    out += css.slice(i, end);
    i = end;
  } else if (dropped.test(css.slice(i))) {
    // Skip the at-rule and its block, including nested blocks.
    let depth = 0;
    for (; i < css.length; i++) {
      if (css[i] === "{") {
        depth++;
      } else if (css[i] === "}" && --depth === 0) {
        i++;
        break;
      }
    }
  } else {
    out += css[i++];
  }
}
process.stdout.write(`${selector} {\n${out.trim()}\n}\n`);
EOF
}

# Print a comment that says which file a generated file came from.
# Arguments: a description of the sources.
generated_header() {
  echo "/* Generated by vendor/update.sh from $1.  Do not edit. */"
}

rm -rf "$VENDOR/djot" "$VENDOR/dompurify" "$VENDOR/temml" "$VENDOR/highlight.js" "$VENDOR/mermaid"

pkg=$(fetch @djot/djot "$DJOT_VERSION")
mkdir "$VENDOR/djot"
cp "$pkg/dist/djot.js" "$pkg/LICENSE" "$VENDOR/djot/"

pkg=$(fetch dompurify "$DOMPURIFY_VERSION")
mkdir "$VENDOR/dompurify"
cp "$pkg/dist/purify.min.js" "$pkg/LICENSE" "$pkg/LICENSE-MPL" "$VENDOR/dompurify/"

pkg=$(fetch temml "$TEMML_VERSION")
mkdir "$VENDOR/temml"
cp "$pkg/dist/temml.mjs" "$pkg/LICENSE" "$VENDOR/temml/"
{
  generated_header "Temml $TEMML_VERSION dist/Temml-Local.css"
  scope_css "$pkg/dist/Temml-Local.css" html.djot-viewer
} > "$VENDOR/temml/temml.css"

pkg=$(fetch @highlightjs/cdn-assets "$HIGHLIGHTJS_VERSION")
mkdir "$VENDOR/highlight.js"
cp "$pkg/es/highlight.min.js" "$pkg/LICENSE" "$VENDOR/highlight.js/"
{
  generated_header "highlight.js $HIGHLIGHTJS_VERSION styles/github.min.css and styles/github-dark.min.css"
  scope_css "$pkg/styles/github.min.css" html.djot-viewer
  echo "@media (prefers-color-scheme: dark) {"
  scope_css "$pkg/styles/github-dark.min.css" html.djot-viewer
  echo "}"
} > "$VENDOR/highlight.js/highlight.css"

pkg=$(fetch mermaid "$MERMAID_VERSION")
mkdir -p "$VENDOR/mermaid/chunks/mermaid.esm.min"
cp "$pkg/dist/mermaid.esm.min.mjs" "$pkg/LICENSE" "$VENDOR/mermaid/"
cp "$pkg"/dist/chunks/mermaid.esm.min/*.mjs "$VENDOR/mermaid/chunks/mermaid.esm.min/"

# The JavaScript files are copied unchanged, so that each one is exactly what
# its license covers.  Some end with a comment that names a source map, which
# is not vendored; DevTools reports the missing map, which is harmless.

echo "Updated the libraries in $VENDOR."
